/*
 * A313099  Coordination sequence Gal.6.259.2 where Gal.u.t.v denotes the
 *          coordination sequence for a vertex of type v in tiling number t in
 *          the Galebach list of u-uniform tilings.
 * https://oeis.org/A313099
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(0) = 1; For n >= 1, let q = floor((n-1)/12) and r = (n-1) mod
 *            12. Define comp[12] = {0,0,0,0,1,1,1,2,2,2,2,3}. Then d = 1 +
 *            4*q + comp[r]; a(n) = 5*n - d. This matches the first 24 terms
 *            and all values generated by the OEIS b-file for n >= 0
 * Range:     u8 n <= 49, u16 n <= 49, u32 n <= 49, u64 n <= 49, u128 n <= 49,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n == 0) {
        return (seq_t)1;
    }
    static const int comp[12] = {0,0,0,0,1,1,1,2,2,2,2,3};
    /* compute offset, quotient and remainder */
    idx_t offset = n - 1;
    idx_t q = offset / 12;
    idx_t r = offset % 12;

    /* compute d = 1 + 4*q + comp[r] in seq_t */
    seq_t d = (seq_t)1 + (seq_t)4 * (seq_t)q + (seq_t)comp[r];

    /* compute a(n) = 5*n - d */
    seq_t result = (seq_t)5 * (seq_t)n - d;
    return result;
}
